🤖 **Comment from Claude working with Aaron Silverman:**

**[P3]** Consider saying per mode what a future timestamp does.

This line reads: "Future timestamps apply immediately; they do not schedule exclusion." Both modes do apply the cutoff at once. In `FutureExperimentsOnly`, though, a cutoff 30 days ahead keeps the subject eligible for an experiment activated yesterday or tomorrow, and skips one activated in 60 days. A sentence per mode would keep readers from expecting immediate exclusion in both.

<details>
<summary><b>Evidence</b> — a run against this PR's core</summary>

```ts
import { evaluateRulesBasedConfiguration } from './evaluation'
import type { UniversalFlagConfigurationV1 } from './ufc-v1'

const logger = { debug: jest.fn(), info: jest.fn(), warn: jest.fn(), error: jest.fn() }
const day = 24 * 60 * 60 * 1000
const iso = (offsetDays: number) => new Date(Date.now() + offsetDays * day).toISOString()

function rules(activation: string): UniversalFlagConfigurationV1 {
  return {
    createdAt: iso(0),
    format: 'SERVER',
    environment: { name: 'test' },
    flags: {
      flag: {
        key: 'flag',
        enabled: true,
        variationType: 'BOOLEAN',
        variations: { on: { key: 'on', value: true }, off: { key: 'off', value: false } },
        allocations: [
          {
            key: 'experiment',
            doLog: true,
            randomizationActivatedAt: activation,
            splits: [{ variationKey: 'on', shards: [] }],
          },
          { key: 'ordinary', doLog: false, splits: [{ variationKey: 'off', shards: [] }] },
        ],
      },
    },
  }
}

describe('a future cutoff in future-experiments-only mode', () => {
  const context = { targetingKey: 's', dd_experimentation_opt_out_at: iso(30) }
  it.each([
    [-1, true],
    [1, true],
    [60, false],
  ])('activation %i days from now: experiment served = %s', (activationDays, served) => {
    // The default differs from the expected value, so a default result fails.
    const result = evaluateRulesBasedConfiguration(
      rules(iso(activationDays)),
      'boolean',
      'flag',
      !served,
      context,
      logger,
      'future_experiments_only'
    )
    expect(result.value).toBe(served)
    expect(result.flagMetadata?.allocationKey).toBe(served ? 'experiment' : 'ordinary')
  })
  it('excludes now in immediate mode', () => {
    const result = evaluateRulesBasedConfiguration(
      rules(iso(-1)),
      'boolean',
      'flag',
      true,
      context,
      logger,
      'immediate'
    )
    expect(result.value).toBe(false)
  })
})
```

